class MyQueue:
    def __init__(self) -> None:
        self._in: list[int] = []
        self._out: list[int] = []

    def push(self, x: int) -> None:
        self._in.append(x)

    def _refill(self) -> None:
        if not self._out:                    # only refill when empty, or the order breaks
            while self._in:
                self._out.append(self._in.pop())

    def pop(self) -> int:
        self._refill()
        return self._out.pop()

    def peek(self) -> int:
        self._refill()
        return self._out[-1]

    def empty(self) -> bool:
        return not self._in and not self._out

q = MyQueue()
q.push(1)
q.push(2)
assert q.peek() == 1
assert q.pop() == 1
q.push(3)                   # arrives while 2 is still in the out stack
assert q.pop() == 2
assert q.pop() == 3
assert q.empty()

