def next_greater(nums: list[int]) -> list[int]:
    result = [-1] * len(nums)
    waiting: list[int] = []               # indices without an answer yet; their values decrease
    for i, value in enumerate(nums):
        while waiting and nums[waiting[-1]] < value:
            result[waiting.pop()] = value
        waiting.append(i)
    return result

