import heapq

def find_kth_largest(nums: list[int], k: int) -> int:
    heap: list[int] = []
    for value in nums:
        heapq.heappush(heap, value)
        if len(heap) > k:
            heapq.heappop(heap)            # at least k values are bigger: it cannot be the answer
    return heap[0]

